  align-items: center !important;
  justify-content: center !important;
  gap: 6px !important;
  padding: 8px 14px !important;
  border-radius: 9999px !important;
  border: 1px solid rgba(255, 255, 255, 0.15) !important;
  background: rgba(255, 255, 255, 0.08) !important;
  color: #f8fafc !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;
  line-height: 1 !important;
  outline: none !important;
}
.edu-refresh-btn:hover {
  background: rgba(255, 255, 255, 0.16) !important;
  border-color: rgba(255, 255, 255, 0.3) !important;
  transform: translateY(-1px) !important;
}
.edu-refresh-btn:active .edu-refresh-svg {
  transform: rotate(180deg);
  transition: transform 0.4s ease;
}
[data-theme="light"] .edu-refresh-btn {
  background: #f1f5f9 !important;
  border-color: #cbd5e1 !important;
  color: #0f172a !important;
}
[data-theme="light"] .edu-refresh-btn:hover {
  background: #e2e8f0 !important;
  border-color: #94a3b8 !important;
}

/* ========================================================================== */
/* PERFECT ALIGNMENT: 4-STEP INTAKE WORKFLOW                                  */
/* ========================================================================== */
.edu-steps-section {
  width: 100% !important;
  padding: 80px 24px !important;
  box-sizing: border-box !important;
}
.edu-steps-section .edu-section-inner {
  max-width: 1160px !important;
  margin: 0 auto !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  text-align: center !important;
}
.edu-steps-section .edu-section-header {
  width: 100% !important;
  max-width: 720px !important;
  margin: 0 auto 48px auto !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  text-align: center !important;
}
.edu-steps-section .edu-section-header .edu-badge {
  display: inline-block !important;
  margin: 0 auto 14px auto !important;
}
.edu-steps-section .edu-section-header h2 {
  font-size: 34px !important;
  font-weight: 800 !important;
  letter-spacing: -0.02em !important;
  margin: 0 auto 12px auto !important;
  text-align: center !important;
  width: 100% !important;
}
.edu-steps-section .edu-section-header p {
  font-size: 16px !important;
  line-height: 1.6 !important;
  margin: 0 auto !important;
  text-align: center !important;
  width: 100% !important;
}

.edu-steps-grid {
  width: 100% !important;
  max-width: 1160px !important;
  margin: 0 auto !important;
  display: grid !important;
  grid-template-columns: repeat(4, 1fr) !important;
  gap: 20px !important;
}
@media (max-width: 992px) {
  .edu-steps-grid {
    grid-template-columns: repeat(2, 1fr) !important;
  }
}
@media (max-width: 576px) {
  .edu-steps-grid {
    grid-template-columns: 1fr !important;
  }
}

.edu-step-card {
  position: relative !important;
  border-radius: 18px !important;
  padding: 32px 20px 28px 20px !important;
  text-align: center !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: flex-start !important;
  box-sizing: border-box !important;
  transition: transform 0.25s ease, box-shadow 0.25s ease !important;
}
.edu-step-card:hover {
  transform: translateY(-4px) !important;
}
.edu-step-num {
  font-size: 13px !important;
  font-weight: 800 !important;
  letter-spacing: 0.05em !important;
  padding: 4px 12px !important;
  border-radius: 9999px !important;
  margin-bottom: 16px !important;
  display: inline-block !important;
  line-height: 1.2 !important;
}
.edu-step-icon {
  font-size: 34px !important;
  margin-bottom: 14px !important;
  line-height: 1 !important;
  display: inline-block !important;
}
.edu-step-card h3 {
  font-size: 18px !important;
  font-weight: 700 !important;
  margin: 0 0 10px 0 !important;
  text-align: center !important;
  width: 100% !important;
}
.edu-step-card p {
  font-size: 14px !important;
  line-height: 1.55 !important;
  margin: 0 !important;
  text-align: center !important;
  width: 100% !important;
}

/* Dark Theme Steps */
[data-theme="dark"] .edu-step-card {
  background: rgba(30, 41, 59, 0.7) !important;
  border: 1px solid rgba(51, 65, 85, 0.7) !important;
  color: #f8fafc !important;
}
[data-theme="dark"] .edu-step-card:hover {
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.4) !important;
  border-color: rgba(194, 136, 47, 0.5) !important;
}
[data-theme="dark"] .edu-step-num {
  color: #fbbf24 !important;
  background: rgba(245, 158, 11, 0.15) !important;
  border: 1px solid rgba(245, 158, 11, 0.3) !important;
}
[data-theme="dark"] .edu-step-card p {
  color: #94a3b8 !important;
}

/* Light Theme Steps */
[data-theme="light"] .edu-step-card {
  background: #ffffff !important;
  border: 1px solid #e2e8f0 !important;
  color: #0f172a !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.04) !important;
}
[data-theme="light"] .edu-step-card:hover {
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.08) !important;
  border-color: #cbd5e1 !important;
}
[data-theme="light"] .edu-step-num {
  color: #b45309 !important;
  background: rgba(245, 158, 11, 0.12) !important;
  border: 1px solid rgba(245, 158, 11, 0.25) !important;
}
[data-theme="light"] .edu-step-card p {
  color: #64748b !important;
}

sp_widget.script:
(function() {
  data.isLoggedIn = gs.isLoggedIn();
  data.userName = gs.getUserDisplayName() || gs.getUserName();
  data.userInitial = data.userName ? data.userName.charAt(0).toUpperCase() : 'U';

  data.hasApplication = false;
  data.applicationStatus = '';
  data.applicationNumber = '';
  data.applicationId = '';

  if (data.isLoggedIn) {
    var userEmail = gs.getUser().getEmail();
    var userName = gs.getUserName();
    var grApp = new GlideRecord('x_1790229_edusph_0_admission_application');
    var qc = grApp.addQuery('sys_created_by', userName);
    if (userEmail) {
      qc.addOrCondition('email', userEmail);
    }
    grApp.orderByDesc('sys_created_on');
    grApp.setLimit(1);
    grApp.query();
    if (grApp.next()) {
      data.hasApplication = true;
      data.applicationId = grApp.getUniqueValue();
      data.applicationNumber = grApp.getValue('app_no') || grApp.getValue('number') || '';
      data.applicationStatus = grApp.getDisplayValue('status') || 'Draft';
    }
  }

  // Stats
  data.stats = { programs: 0, colleges: 0, seats: 0, applications: 0 };

  var grProg = new GlideAggregate('x_1790229_edusph_0_program');
  grProg.addQuery('active', true);
  grProg.addAggregate('COUNT');
  grProg.query();
  if (grProg.next()) data.stats.programs = parseInt(grProg.getAggregate('COUNT')) || 0;

  var grCol = new GlideAggregate('x_1790229_edusph_0_college');
  grCol.addQuery('status', 'active');
  grCol.addAggregate('COUNT');
  grCol.query();
  if (grCol.next()) data.stats.colleges = parseInt(grCol.getAggregate('COUNT')) || 0;

  var grSeats = new GlideAggregate('x_1790229_edusph_0_coll_prog');
  grSeats.addQuery('approved', true);
  grSeats.addAggregate('SUM', 'intake_seats');
  grSeats.query();
  if (grSeats.next()) data.stats.seats = parseInt(grSeats.getAggregate('SUM', 'intake_seats')) || 0;

  var grApps = new GlideAggregate('x_1790229_edusph_0_admission_application');
  grApps.addAggregate('COUNT');
  grApps.query();
  if (grApps.next()) data.stats.applications = parseInt(grApps.getAggregate('COUNT')) || 0;

  // College Programs with explicit Program Name resolution
  data.collegePrograms = [];
  var grCP = new GlideRecord('x_1790229_edusph_0_coll_prog');
  grCP.addQuery('approved', true);
  grCP.query();
  while (grCP.next()) {
    var progName = grCP.program.name ? grCP.program.name.toString() : grCP.program.getDisplayValue();
    var colName = grCP.college.name ? grCP.college.name.toString() : grCP.college.getDisplayValue();
    if (!progName) {
      progName = "B.Tech Engineering Program";
    }
    data.collegePrograms.push({
      sys_id: grCP.getUniqueValue(),
      college_name: colName,
      program_name: progName,
      seats: parseInt(grCP.getValue('intake_seats')) || 60,
      approved: true
    });
  }
})();
